const SEA_SUNLIGHT = vec3f(1.47, 1.42, 1.3);
const SEA_DAY_SKYLIGHT = vec3f(0.22, 0.26, 0.3);
const SEA_NIGHT_SKYLIGHT = vec3f(0.04, 0.05, 0.075);

